import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        long cap = r.nextLong();
        int n = r.nextInt(), m = r.nextInt();
        long[] fgId = new long[n], fgMem = new long[n];
        for (int i = 0; i < n; i++) { fgId[i] = r.nextLong(); fgMem[i] = r.nextLong(); }
        TreeMap<Long, List<Long>> groups = new TreeMap<>();  // background memory -> ids
        for (int j = 0; j < m; j++) {
            long id = r.nextLong(), mem = r.nextLong();
            groups.computeIfAbsent(mem, key -> new ArrayList<>()).add(id);
        }
        long best = -1;
        for (int i = 0; i < n; i++) {
            Long p = groups.floorKey(cap - fgMem[i]);  // largest background memory that still fits
            if (p != null) best = Math.max(best, fgMem[i] + p);
        }
        List<long[]> answer = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Long> others = groups.get(best - fgMem[i]);
            if (others != null) for (long other : others) answer.add(new long[] {fgId[i], other});
        }
        answer.sort((p, q) -> p[0] != q[0] ? Long.compare(p[0], q[0]) : Long.compare(p[1], q[1]));
        StringBuilder sb = new StringBuilder("[");
        if (answer.isEmpty()) sb.append("[]");
        for (int i = 0; i < answer.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('[').append(answer.get(i)[0]).append(',').append(answer.get(i)[1]).append(']');
        }
        System.out.println(sb.append(']'));
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"cmp"
	"os"
	"slices"
	"sort"
	"strconv"
)

func main() {
	capacity, n, m := readInt(), readInt(), readInt()
	fg := make([][2]int, n) // (id, memory)
	for i := range fg {
		fg[i] = [2]int{readInt(), readInt()}
	}
	groups := map[int][]int{} // background memory -> ids
	for j := 0; j < m; j++ {
		id, mem := readInt(), readInt()
		groups[mem] = append(groups[mem], id)
	}
	memories := make([]int, 0, len(groups))
	for mem := range groups {
		memories = append(memories, mem)
	}
	slices.Sort(memories)
	best := -1
	for _, f := range fg {
		p := sort.SearchInts(memories, capacity-f[1]+1) - 1 // largest memory <= capacity - f
		if p >= 0 {
			best = max(best, f[1]+memories[p])
		}
	}
	var answer [][2]int
	for _, f := range fg {
		for _, other := range groups[best-f[1]] {
			answer = append(answer, [2]int{f[0], other})
		}
	}
	slices.SortFunc(answer, func(p, q [2]int) int {
		return cmp.Or(cmp.Compare(p[0], q[0]), cmp.Compare(p[1], q[1]))
	})
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteByte('[')
	if len(answer) == 0 {
		w.WriteString("[]")
	}
	for i, p := range answer {
		if i > 0 {
			w.WriteByte(',')
		}
		w.WriteString("[" + strconv.Itoa(p[0]) + "," + strconv.Itoa(p[1]) + "]")
	}
	w.WriteString("]\n")
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
